// Error Workflow: any workflow that sets this as its "Error workflow" lands here when it fails.
const execution = $json.execution ?? {};
const trigger = $json.trigger ?? {};
const workflow = $json.workflow ?? {};
const error = execution.error ?? trigger.error ?? {};
const failedNode = execution.lastNodeExecuted ?? error.node?.name ?? 'unknown node';
const message = String(error.message ?? 'Unknown error').slice(0, 500);
const link = execution.url ? `\n🔗 ${execution.url}` : '';
return [{
  json: {
    content: `🚨 **Workflow failed: ${workflow.name ?? 'unknown'}**\nNode: **${failedNode}** · mode: ${execution.mode ?? 'trigger'} · execution ${execution.id ?? '—'}\n> ${message}${link}`,
    workflow: workflow.name, failedNode, message,
  },
}];
